<style>
.seller-returns{max-width:1500px;margin:auto;color:#173f35;font-size:13px}.seller-returns [hidden]{display:none!important}.seller-returns h1{font-size:25px;font-weight:700;letter-spacing:-.04em;line-height:1.3}.seller-returns h2{font-size:15px;font-weight:600;margin:0 0 6px}.seller-returns h3{font-size:12px;font-weight:600}.seller-returns p{line-height:1.7;margin:5px 0}.rr-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:10px 0 20px}.rr-heading p,.rr-muted{color:#71817b}.rr-eyebrow{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.12em;font-weight:600;color:#71817b;margin-bottom:8px}.rr-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:20px}.rr-card{min-width:0;background:white;border:1px solid #dde6e1;border-radius:16px;padding:20px;box-shadow:0 8px 25px #173f3506}.rr-summary strong{display:block;font-size:26px;font-weight:600}.rr-summary small{display:block;color:#71817b;margin-top:8px;font-size:10px}.rr-list{padding:0;overflow:hidden}.rr-section-heading{padding:20px;display:flex;justify-content:space-between;align-items:center;gap:15px;border-bottom:1px solid #edf1ef}.rr-section-heading p{color:#71817b;font-size:12px}.rr-count{white-space:nowrap;font-size:11px;color:#71817b}.rr-filters{padding:16px 20px}.rr-search>label,.rr-recommendation>label{display:block;font-weight:600;font-size:11px;margin-bottom:6px}.rr-search>div{display:flex;gap:8px}.rr-search input{flex:1;min-width:0}.seller-returns :is(input[type=search],select,textarea){width:100%;border:1px solid #d4e0d9;border-radius:9px;background:white;font:inherit;padding:10px 12px;color:#173f35}.seller-returns textarea{resize:vertical;min-height:95px}.rr-button{display:inline-flex;align-items:center;justify-content:center;min-height:40px;border:1px solid #173f35;border-radius:9px;padding:9px 14px;background:#173f35;color:white;font:inherit;font-size:12px;font-weight:600;text-decoration:none;cursor:pointer;white-space