e-flex;min-height:36px;align-items:center;white-space:nowrap}.rr-badge{display:inline-block;max-width:100%;font-size:10px;padding:5px 9px;border-radius:20px;background:#eef3f0;color:#52635b;font-weight:600;line-height:1.5}.rr-status-submitted{color:#9a610c;background:#fff6df}.rr-status-seller_responded,.rr-status-under_review{color:#316585;background:#eaf3fa}.rr-status-admin_approved{color:#157054;background:#e5f7ee}.rr-status-admin_rejected{color:#a34040;background:#fff0ef}.rr-empty{text-align:center;padding:30px 15px;color:#71817b}.rr-empty h3{font-size:15px;color:#173f35}.rr-empty .rr-button{margin-top:12px}.rr-list-footer{padding:16px 20px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;font-size:11px;color:#71817b}.rr-back{display:inline-flex;min-height:36px;align-items:center}.rr-detail-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:20px}.rr-detail-main,.rr-detail-side{display:flex;flex-direction:column;gap:16px;min-width:0}.rr-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-top:20px}.rr-facts dt{color:#71817b;font-size:11px;margin-bottom:5px}.rr-facts dd{overflow-wrap:anywhere;font-weight:500}.rr-divider{border-top:1px solid #edf1ef;padding-top:16px;margin-top:18px}.rr-preserve{white-space:pre-wrap;overflow-wrap:anywhere}.rr-evidence a{display:flex;flex-direction:column;gap:5px;padding:12px 0;border-bottom:1px solid #edf1ef;overflow-wrap:anywhere}.rr-evidence span{font-size:12px;color:#71817b}.rr-evidence small{font-size:10px;color:#71817b}.rr-timeline{list-style:none;margin:16px 0 0;padding:0}.rr-timeline li{border-left:2px solid #dde6e1;padding:0 0 18px 14px;display:flex;flex-direction:column;gap:4px}.rr-timeline strong{font-weight:500;font-size:12px}.rr-timeline time{font-size:10px;color:#71817b}.rr-recommendation{margin-top:20px}.rr-recommendation select{margin-bottom:16px}.rr-recommendation>.rr-button{margin-top:14px;width:100%}.rr-feedback{border:1px solid